  "harness": "claude-code",
  "dry_run": true,
  "remove": false,
  "target": {
    "brain": {
      "kind": "new-local-pglite",
      "path": "/harness-state/.gbrain/brain.pglite",
      "config_dir": "/harness-state/.gbrain"
    },
    "source": {
      "id": null,
      "pinned": false,
      "from": "brain-default"
    },
    "transport": "local-stdio",
    "launcher": "/harness-state/.bun/bin/gbrain",
    "surface": "starter",
    "advertise": "verbs",
    "registration_owner": "none",
    "live_owner": null,
    "scope": "user",
    "name": "gbrain",
