    "settings_path": "/harness-state/claude/settings.json",
    "receipt_path": "/harness-state/claude/.gbrain-connection-claude-code-gbrain.json"
  },
  "consent": {
    "wiring_scope": {
      "value": {
        "scope": "user",
        "hooks": "read-context"
      },
      "source": "default"
    },
    "capture": {
      "value": "declined",
      "source": "default"
    },
    "providers": {
      "value": "declined",
      "source": "default"
    }
  },
  "steps": [
    {
      "step": "receipt",
      "action": "write",
      "detail": "/harness-state/claude/.gbrain-connection-claude-code-gbrain.json"
    },
    {
      "step": "brain",
      "action": "write",
      "detail": "would run: /harness-state/.bun/bin/gbrain init --pglite --no-embedding --json"
    },
    {
      "step": "mcp",
      "action": "write",
      "detail": "'gbrain' in /harness-state/claude/.claude.json"
    },
    {
      "step": "hooks",
      "action": "write",
      "detail": "SessionStart, UserPromptSubmit in /harness-state/claude/settings.json"
    }
  ],
  "preserved": [],
  "instructions": {
    "harness": "claude-code",
    "path": "/harness-state/claude/CLAUDE.md",
    "role": "Claude Code user instructions",
    "decision": {
      "value": "accepted",
      "source": "default"
    },
    "action": "write",
    "state_before": "no_file",
    "detail": "brain-first block in new file /harness-state/claude/CLAUDE.md"
  },
  "skills": {
    "harness": "claude-code",
    "path": "/harness-state/claude/CLAUDE.md",
    "decision": {
      "value": "off",
      "source": "default"
    },
    "action": "skip",
    "state_before": "no_file",
    "detail": "skill loading off: no skills index in /harness-state/claude/CLAUDE.md"
