      "code": "first_run_decisions",
      "kind": "ask",
      "why": "Setup is complete and memory works now. One optional choice remains; nothing is written until the user answers.",
      "user_message": "gbrain is set up, so memory works now. Want a personal or company brain? I can add starter pages (facts, voice and decisions) and import a notes or docs folder you pick.",
      "decisions": [
        {
          "id": "brain_shape",
          "question": "Give this brain a shape? A personal brain gets three empty starter pages (facts about you, your voice, how you decide) and a notes folder you pick, imported read only. A company brain gets empty pages for company facts, decisions, pricing, customers, calls and playbooks in a company source, and a docs folder you pick. Setup tells the agent to read them. Nothing is invented.",
          "options": [
            {
              "id": "personal",
              "label": "Personal brain, no notes folder yet",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "personal"
              ]
            },
            {
              "id": "company",
              "label": "Company brain, just me (add --docs <folder> for company docs, --transcripts <folder> for call transcripts)",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "company"
              ]
            },
            {
              "id": "both",
              "label": "Personal and company brain, just me",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "both"
              ]
            },
            {
              "id": "company_team",
              "label": "Company brain shared with a team (prints where it lives; creates nothing)",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "company",
                "--team"
              ]
            },
            {
              "id": "none",
              "label": "No starter pages (memory works as it is)"
            }
          ],
          "default": "none",
          "default_reason": "Nothing is written until the user picks; memory already works without it."
        }
      ],
      "contract_version": 1
    }
  ]
}

